#!/usr/bin/env python3
"""
Injects canonical + Open Graph + Twitter Card + JSON-LD into every page.

    python3 scripts/build_seo.py --dry-run
    python3 scripts/build_seo.py

IDEMPOTENT. Everything it writes lives between the markers

    <!-- SEO:BEGIN (generated by scripts/build_seo.py — do not edit by hand) -->
    <!-- SEO:END -->

so re-running replaces that block rather than appending a second copy. Edit this
script, never the block. Anything outside the markers is left untouched, which is
what lets it run safely against 71KB of hand-written homepage.

Prices, URLs and identity all come from scripts/seo_config.py. Structured data that
disagrees with the visible page is a penalty risk, so the offers in the schema are
the same constants the pricing section renders from.
"""
import argparse
import html as H
import json
import os
import re
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import seo_config as C  # noqa: E402

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
BEGIN = "<!-- SEO:BEGIN (generated by scripts/build_seo.py — do not edit by hand) -->"
END = "<!-- SEO:END -->"

# ---------------------------------------------------------------------------
# Per-page metadata.
#
# Titles <= 60 chars and descriptions <= 155 chars, because Google truncates past
# roughly that and a truncated title is a wasted title.
#
# The homepage title previously read "Toolbelt - The #1 Invoice App for
# Contractors". "#1" is a claim we cannot substantiate — there is no ranking, no
# award, and no source. It is also a weak title for search: it spends its first
# and most valuable characters on the brand name and a boast rather than on the
# phrase people actually type. Replaced with the keyword first, brand last.
# ---------------------------------------------------------------------------
